230	export class WorkspaceRegistry {
231	  private constructor(
232	    private readonly env: RegistryEnv,
233	    private key: WorkspacesKey,
234	    /** preferences.json did not parse (or the first registration could not be written): write nothing. */
235	    readonly readOnly: boolean,
236	  ) {}
