242	  /**
243	   * Load the registry, migrating a pre-workspaces install on its first launch and adopting a
244	   * folder an older version switched to. Additive only: it writes
245	   * `.kaipu/workspace/identity.json` and the `workspaces` key, and nothing else.
246	   */
247	  static async open(env: RegistryEnv): Promise<WorkspaceRegistry> {
248	    const read = await readPreferences(env.preferencesFile);
249	    if (read.kind === "corrupt") return WorkspaceRegistry.readOnlyFallback(env);
250	    const preferences = read.kind === "ok" ? read.preferences : {};
251	    const vaultPath =
252	      typeof preferences.vaultDirectory === "string" && preferences.vaultDirectory
253	        ? preferences.vaultDirectory
254	        : env.defaultDirectory;
255	
256	    if (preferences.workspaces === undefined) {
257	      return WorkspaceRegistry.migrate(env, vaultPath, vaultPath === env.defaultDirectory);
258	    }
259	    const key = parseWorkspacesKey(preferences.workspaces);
260	    // A key this version cannot read (hand edit, a future version): leave it alone.
261	    if (!key) return WorkspaceRegistry.readOnlyFallback(env, vaultPath);
262	    const registry = new WorkspaceRegistry(env, key, false);
263	    await registry.reconcile(vaultPath);
264	    if (!registry.key.kaipuColorApplied) await registry.upgradeDefaultColor();
265	    return registry;
266	  }
