268	  /** The library as today, under an in-memory id; nothing is written until the next launch. */
269	  private static async readOnlyFallback(
270	    env: RegistryEnv,
271	    path: string = env.defaultDirectory,
272	  ): Promise<WorkspaceRegistry> {
273	    const identity = await readIdentity(path);
274	    const entry: WorkspaceEntry =
275	      identity.kind === "ok"
276	        ? entryFromIdentity(identity.identity, path, 0)
277	        : {
278	            id: env.newId(),
279	            path,
280	            name: DEFAULT_WORKSPACE_NAME,
281	            color: DEFAULT_WORKSPACE_COLOR,
282	            initials: deriveInitials(DEFAULT_WORKSPACE_NAME),
283	            addedAt: 0,
284	          };
285	    return new WorkspaceRegistry(
286	      env,
287	      { version: 1, activeId: entry.id, legacyCloudOwnerId: entry.id, entries: [entry] },
288	      true,
289	    );
290	  }
