292	  /** First launch after the upgrade: the current library becomes "Default workspace". */
293	  private static async migrate(
294	    env: RegistryEnv,
295	    path: string,
296	    isDefault: boolean,
297	  ): Promise<WorkspaceRegistry> {
298	    const now = WorkspaceRegistry.now(env);
299	    // Today's behaviour: the default folder is created on first use.
300	    if (isDefault) await mkdir(path, { recursive: true }).catch(() => {});
301	    const existing = await readIdentity(path);
302	    let entry: WorkspaceEntry;
303	    if (existing.kind === "ok") {
304	      // A rerun after a crash between the two writes: reuse the id, never mint a second.
305	      entry = entryFromIdentity(existing.identity, path, now);
306	    } else {
307	      const identity: WorkspaceIdentity = {
308	        version: 1,
309	        id: env.newId(),
310	        name: DEFAULT_WORKSPACE_NAME,
311	        color: DEFAULT_WORKSPACE_COLOR,
312	        initials: deriveInitials(DEFAULT_WORKSPACE_NAME),
313	        createdAt: now,
314	      };
315	      entry = entryFromIdentity(identity, path, now);
316	      if (existing.kind === "absent") {
317	        try {
318	          await writeIdentity(path, identity);
319	        } catch {
320	          // Unplugged or read-only: registered anyway, initialized on the first reach.
321	          entry.pendingInit = true;
322	        }
323	      } else {
324	        // An identity.json we cannot read is never overwritten.
325	        entry.pendingInit = true;
326	      }
327	    }
328	    const key: WorkspacesKey = {
329	      version: 1,
330	      activeId: entry.id,
331	      legacyCloudOwnerId: entry.id,
332	      // Born with the brand color: there is nothing to upgrade, now or on a later launch.
333	      kaipuColorApplied: true,
334	      entries: [entry],
335	    };
336	    const registry = new WorkspaceRegistry(env, key, false);
337	    try {
338	      await registry.persist({ mirrorVault: false });
339	    } catch {
340	      // The registry could not be stored: run as today and retry on the next launch.
341	      return new WorkspaceRegistry(env, key, true);
342	    }
343	    return registry;
344	  }
