346	  /**
347	   * `vaultDirectory` no longer matches the active entry: an older version changed the folder
348	   * while downgraded. Adopt that folder (by its identity id, else its path, else as a new
349	   * entry) and make it active, so the change is not ignored after the re-upgrade.
350	   */
351	  private async reconcile(vaultPath: string): Promise<void> {
352	    const active = this.key.entries.find((e) => e.id === this.key.activeId);
353	    if (active && samePath(active.path, vaultPath)) return;
354	    const identity = await readIdentity(vaultPath);
355	    let target: WorkspaceEntry | undefined;
356	    if (identity.kind === "ok") {
357	      target = this.key.entries.find((e) => e.id === identity.identity.id);
358	      if (target) target.path = vaultPath;
359	    }
360	    target ??= this.key.entries.find((e) => samePath(e.path, vaultPath));
361	    if (!target) {
362	      target = await this.register(vaultPath, identity);
363	      if (!target) return; // the folder is gone too: keep the registry's own active entry
364	    }
365	    this.key.activeId = target.id;
366	    try {
367	      await this.persist({ mirrorVault: true });
368	    } catch (error) {
369	      // The app still opens that folder (vaultDirectory already names it); the registry
370	      // catches up on the next write or launch.
371	      console.error("workspaces: could not store the adopted folder", error);
372	    }
373	  }
