375	  /** Make an entry for a folder the registry does not know. Null when it cannot be reached. */
376	  private async register(
377	    path: string,
378	    identity: Awaited<ReturnType<typeof readIdentity>>,
379	  ): Promise<WorkspaceEntry | undefined> {
380	    const now = WorkspaceRegistry.now(this.env);
381	    if (identity.kind === "ok") {
382	      const entry = entryFromIdentity(identity.identity, path, now);
383	      this.key.entries.push(entry);
384	      return entry;
385	    }
386	    if (identity.kind === "unreadable" || !(await isDirectory(path))) return undefined;
387	    const name = normalizeWorkspaceName(basename(path)) ?? DEFAULT_WORKSPACE_NAME;
388	    const minted: WorkspaceIdentity = {
389	      version: 1,
390	      id: this.env.newId(),
391	      name,
392	      color: nextWorkspaceColor(this.key.entries.map((e) => e.color)),
393	      initials: deriveInitials(name),
394	      createdAt: now,
395	    };
396	    const entry = entryFromIdentity(minted, path, now);
397	    try {
398	      await writeIdentity(path, minted);
399	    } catch {
400	      entry.pendingInit = true;
401	    }
402	    this.key.entries.push(entry);
403	    return entry;
404	  }
