426	  /**
427	   * The one-time upgrade (part 1b): a "Default workspace" that part 1 migrated as rose takes
428	   * Kaipu's brand color. The marker is stored first, in the same write, so it runs once; the
429	   * folder's identity.json follows through `pendingColorUpgrade`, which also covers a folder
430	   * that is not connected right now: when it is back, the file is written only if it still
431	   * holds the old Default and rose. A name or color the user already changed, here or on
432	   * another Mac, is left as it is.
433	   */
434	  private async upgradeDefaultColor(): Promise<void> {
435	    const owner = this.get(this.key.legacyCloudOwnerId);
436	    let upgrade = owner?.name === DEFAULT_WORKSPACE_NAME && owner.color === "rose";
437	    if (owner && upgrade) {
438	      const file = await readIdentity(owner.path);
439	      // The folder's own file wins (renamed or recolored on another Mac): leave it as it is,
440	      // and a probe will refresh this Mac's cache from it.
441	      if (
442	        file.kind === "ok" &&
443	        (file.identity.color !== "rose" || file.identity.name !== DEFAULT_WORKSPACE_NAME)
444	      ) {
445	        upgrade = false;
446	      }
447	      if (file.kind === "unreadable") upgrade = false;
448	    }
449	    try {
450	      await this.update((key) => {
451	        key.kaipuColorApplied = true;
452	        if (owner && upgrade) {
453	          owner.color = DEFAULT_WORKSPACE_COLOR;
454	          owner.pendingColorUpgrade = true;
455	        }
456	      });
457	    } catch (error) {
458	      // preferences.json could not be written: retried on the next launch.
459	      console.error("workspaces: could not store the color upgrade", error);
460	      return;
461	    }
462	    if (owner && upgrade) await this.availability(owner.id);
463	  }
