465	  /** The folder next to the Default workspace's, or the nearest reachable fallback. */
466	  private async newWorkspaceParent(): Promise<string | null> {
467	    const defaultEntry =
468	      this.get(this.key.legacyCloudOwnerId) ??
469	      this.key.entries.find((e) => this.isDefaultPath(e.path));
470	    for (const candidate of [defaultEntry?.path, this.env.defaultDirectory, this.active().path]) {
471	      if (!candidate) continue;
472	      const parent = dirname(candidate);
473	      if (await isDirectory(parent)) return parent;
474	    }
475	    return null;
476	  }
