478	  /**
479	   * Where "New workspace" would put `name`'s folder, and whether it can be used: `Kaipu Record
480	   * — <name>` next to the Default workspace's folder. Read-only; creates nothing.
481	   */
482	  async checkNewLocation(name: string): Promise<LocationCheck> {
483	    const normalized = validateWorkspaceName(name, []);
484	    if (!normalized.ok) return { path: null, state: "parent-missing" };
485	    const parent = await this.newWorkspaceParent();
486	    if (!parent) return { path: null, state: "parent-missing" };
487	    const path = join(parent, newWorkspaceFolderName(normalized.name));
488	    try {
489	      if (!(await stat(path)).isDirectory()) return { path, state: "not-empty" };
490	      const content = (await readdir(path)).filter((n) => !IGNORED_FOLDER_ENTRIES.has(n));
491	      return { path, state: content.length === 0 ? "empty" : "not-empty" };
492	    } catch (error) {
493	      // Nothing there is the good case; anything else (no permission) cannot be used.
494	      return (error as NodeJS.ErrnoException).code === "ENOENT"
495	        ? { path, state: "free" }
496	        : { path, state: "not-empty" };
497	    }
498	  }
