500	  /**
501	   * Create a workspace in a NEW folder (the owner's request, part 1b): `Kaipu Record — <name>`
502	   * next to the Default workspace's. Writes only Kaipu's own files; a folder that is there and
503	   * not empty is refused untouched. Does not switch.
504	   */
505	  async create(input: { name: string; color: string }): Promise<CreateOutcome> {
506	    if (this.readOnly) return { ok: false, reason: "read-only" };
507	    const checked = validateWorkspaceName(input.name, this.key.entries);
508	    if (!checked.ok) {
509	      return { ok: false, reason: checked.reason === "taken" ? "name-taken" : "invalid-name" };
510	    }
511	    if (!isTagColor(input.color)) return { ok: false, reason: "invalid-color" };
512	    const location = await this.checkNewLocation(checked.name);
513	    if (!location.path) return { ok: false, reason: "parent-missing" };
514	    if (location.state === "not-empty") return { ok: false, reason: "exists" };
515	
516	    const path = location.path;
517	    let madeFolder = false;
518	    if (location.state === "free") {
519	      try {
520	        // One level, never recursive: a missing parent stays missing.
521	        await mkdir(path);
522	        madeFolder = true;
523	      } catch (error) {
524	        const code = (error as NodeJS.ErrnoException).code;
525	        return { ok: false, reason: code === "EEXIST" ? "exists" : "not-writable" };
526	      }
527	    }
528	    const undo = async (): Promise<void> => {
529	      await removeIdentity(path);
530	      if (madeFolder) await rmdir(path).catch(() => {});
531	    };
532	    const identity: WorkspaceIdentity = {
533	      version: 1,
534	      id: this.env.newId(),
535	      name: checked.name,
536	      color: input.color,
537	      initials: deriveInitials(checked.name),
538	      createdAt: WorkspaceRegistry.now(this.env),
539	    };
540	    try {
541	      await writeIdentity(path, identity);
542	    } catch {
543	      await undo();
544	      return { ok: false, reason: "not-writable" };
545	    }
546	    const entry = entryFromIdentity(identity, path, identity.createdAt);
547	    try {
548	      await this.update((key) => {
549	        // Re-checked inside the write: two creates cannot both take one name.
550	        if (validateWorkspaceName(checked.name, key.entries).ok === false)
551	          throw new NameTakenError();
552	        key.entries.push(entry);
553	      });
554	    } catch (error) {
555	      await undo();
556	      return { ok: false, reason: error instanceof NameTakenError ? "name-taken" : "not-writable" };
557	    }
558	    return { ok: true, entry };
559	  }
