97	/** The capture target was unplugged or replaced: refuse, never save anywhere else. */
98	export class WorkspaceNotConnectedError extends Error {
99	  constructor(readonly workspaceName: string) {
100	    const t = createMainTranslator(getAppSettings().locale);
101	    super(t("workspaces.notConnectedError", { name: workspaceName }));
102	    this.name = "WorkspaceNotConnectedError";
103	  }
104	}
