106	/**
107	 * The active workspace, checked to be connected, for a capture that is about to start.
108	 * Throws `WorkspaceNotConnectedError` otherwise; a switch in progress counts as stale.
109	 */
110	export async function requireCaptureWorkspace(): Promise<WorkspaceEntry> {
111	  const reg = requireRegistry();
112	  if (workspaceGate().switching) throw new StaleWorkspaceError();
113	  const active = reg.active();
114	  const { availability, id } = await reg.availability(active.id);
115	  if (workspaceGate().adopt(active.id, id, reg.active().id)) void broadcastState();
