122	  const reg = requireRegistry();
123	  const paths: string[] = [];
124	  // A copy: a probe may update an entry (a pending one adopting its folder's id).
125	  for (const entry of reg.entries().slice()) {
126	    const { availability } = await reg.availability(entry.id);
127	    if (availability.state === "available") paths.push(entry.path);
