224	/** Folder picker for Add workspace; initializes or adopts the folder, then switches to it. */
225	async function addWorkspace(sender: Electron.WebContents): Promise<WorkspaceAddResult> {
226	  const reg = requireRegistry();
227	  if (reg.readOnly) return { ok: false, reason: "read-only" };
228	  const window = BrowserWindow.fromWebContents(sender);
229	  const t = createMainTranslator(getAppSettings().locale);
230	  const options: Electron.OpenDialogOptions = {
231	    title: t("dialogs.addWorkspace"),
232	    buttonLabel: t("dialogs.addWorkspaceButton"),
233	    properties: ["openDirectory", "createDirectory"],
234	  };
235	  const picked = window
236	    ? await dialog.showOpenDialog(window, options)
237	    : await dialog.showOpenDialog(options);
238	  const chosen = picked.filePaths[0];
239	  if (picked.canceled || !chosen) return { ok: false, reason: "cancelled" };
240	
241	  const outcome = await reg.add(chosen);
242	  if (!outcome.ok) {
243	    if (outcome.reason !== "read-only") {
244	      const message = { type: "error" as const, message: t("dialogs.folderUnusable") };
