257	  await reg.dismissHint();
258	  const { availability } = await reg.availability(outcome.entry.id);
259	  // Then make it the active one, through the same transaction as any other switch. A
260	  // refusal (a recording running) leaves it registered and inactive.
261	  await runSwitch(outcome.entry.id);
262	  await broadcastState();
263	  return { ok: true, workspace: toWorkspaceView(outcome.entry, availability, null) };
264	}
265	
266	/**
267	 * New workspace: a new folder next to the Default workspace's, only Kaipu's files in it, then
268	 * the same switch as any other. A refused switch (a recording running) leaves it registered.
269	 */
270	async function createWorkspace(input: unknown): Promise<WorkspaceCreateResult> {
271	  const reg = requireRegistry();
272	  const { name, color } = (input ?? {}) as { name?: unknown; color?: unknown };
273	  if (typeof name !== "string") return { ok: false, reason: "invalid-name" };
274	  if (typeof color !== "string") return { ok: false, reason: "invalid-color" };
275	  const outcome = await reg.create({ name, color });
276	  if (!outcome.ok) return outcome;
277	  await reg.dismissHint();
278	  const { availability } = await reg.availability(outcome.entry.id);
279	  const switchResult = await runSwitch(outcome.entry.id);
280	  await broadcastState();
281	  return {
282	    ok: true,
283	    workspace: toWorkspaceView(outcome.entry, availability, null),
284	    switchResult,
285	  };
286	}
287	
288	async function editWorkspace(input: unknown): Promise<WorkspaceEditResult> {
289	  const reg = requireRegistry();
290	  const { id, name, color } = (input ?? {}) as { id?: unknown; name?: unknown; color?: unknown };
291	  if (typeof id !== "string") return { ok: false, reason: "unknown" };
292	  const outcome = await reg.edit(id, {
293	    ...(typeof name === "string" ? { name } : {}),
294	    ...(typeof color === "string" ? { color } : {}),
295	  });
296	  if (!outcome.ok) return outcome;
297	  const { availability } = await reg.availability(outcome.entry.id);
298	  // The window title shows the active workspace's name, and the tiles show the initials.
299	  refreshTitles();
300	  await broadcastState();
301	  return {
302	    ok: true,
303	    workspace: toWorkspaceView(outcome.entry, availability, null),
304	    savedToFolder: outcome.savedToFolder,
305	  };
306	}
307	
308	/**
309	 * "Change folder…": the native folder picker, then the workspace is pointed at that folder.
310	 * Relocating never moves or copies files; the rules are in `relocate.ts` and the registry.
311	 */
312	async function relocateFolder(
313	  sender: Electron.WebContents,
314	  id: unknown,
315	): Promise<WorkspaceRelocateResult> {
316	  const reg = requireRegistry();
317	  const deps = { ...activeTransactionDeps(), registry: reg };
318	  if (typeof id !== "string") return { ok: false, reason: "unknown" };
319	  // Locked or read-only: say so now, instead of after the user picked a folder.
320	  const refused = relocateRefusal(deps, id);
321	  if (refused) return refused;
322	  const entry = reg.get(id);
323	  if (!entry) return { ok: false, reason: "unknown" };
324	
325	  const window = BrowserWindow.fromWebContents(sender);
326	  const t = createMainTranslator(getAppSettings().locale);
327	  const options: Electron.OpenDialogOptions = {
328	    title: t("dialogs.relocateWorkspace", { name: entry.name }),
329	    buttonLabel: t("dialogs.relocateWorkspaceButton"),
330	    // Where it was: a moved folder is usually next to where it used to be.
331	    defaultPath: dirname(entry.path),
332	    properties: ["openDirectory", "createDirectory"],
333	  };
334	  const picked = window
335	    ? await dialog.showOpenDialog(window, options)
336	    : await dialog.showOpenDialog(options);
337	  const chosen = picked.filePaths[0];
338	  if (picked.canceled || !chosen) return { ok: false, reason: "cancelled" };
339	
340	  const outcome = await relocateWorkspace(deps, id, chosen);
341	  if (!outcome.ok) return outcome;
342	  const { availability } = await reg.availability(outcome.entry.id);
343	  // The active workspace re-lists inside its transaction; any other one only needs the state.
344	  refreshTitles();
345	  await broadcastState();
346	  return {
347	    ok: true,
348	    workspace: toWorkspaceView(reg.get(outcome.entry.id) ?? outcome.entry, availability, null),
349	    ...(outcome.unchanged ? { unchanged: true as const } : {}),
350	  };
351	}
352	
353	export function registerWorkspaceHandlers(deps: WorkspaceHost): void {
354	  host = deps;
355	  ipcMain.handle(IPC_CHANNELS.workspacesList, () => listState());
356	  ipcMain.handle(IPC_CHANNELS.workspacesSwitch, (_event, id: unknown) =>
357	    typeof id === "string" ? runSwitch(id) : { ok: false, reason: "unknown" },
358	  );
359	  ipcMain.handle(IPC_CHANNELS.workspacesAdd, (event) => addWorkspace(event.sender));
360	  ipcMain.handle(IPC_CHANNELS.workspacesCreate, (_event, input: unknown) => createWorkspace(input));
361	  ipcMain.handle(IPC_CHANNELS.workspacesEdit, (_event, input: unknown) => editWorkspace(input));
362	  ipcMain.handle(IPC_CHANNELS.workspacesRelocate, (event, id: unknown) =>
363	    relocateFolder(event.sender, id),
364	  );
365	  ipcMain.handle(
366	    IPC_CHANNELS.workspacesCheckLocation,
367	    (_event, name: unknown): Promise<LocationCheck> =>
368	      typeof name === "string"
369	        ? requireRegistry().checkNewLocation(name)
370	        : Promise.resolve({ path: null, state: "parent-missing" }),
371	  );
372	  ipcMain.handle(
373	    IPC_CHANNELS.workspacesRemove,
374	    async (_event, id: unknown): Promise<WorkspaceRemoveResult> => {
375	      if (typeof id !== "string") return { ok: false, reason: "unknown" };
376	      const result = await requireRegistry().remove(id);
377	      if (result.ok) {
378	        refreshTitles();
379	        await broadcastState();
380	      }
381	      return result;
382	    },
383	  );
384	  ipcMain.handle(IPC_CHANNELS.workspacesOpenFolder, async (_event, id: unknown) => {
385	    const entry = typeof id === "string" ? requireRegistry().get(id) : undefined;
386	    if (!entry) return;
387	    // shell.openPath never creates the folder: a missing one reports an error string.
388	    const error = await shell.openPath(entry.path);
389	    if (error) console.error("failed to open the workspace folder", error);
390	  });
391	  ipcMain.handle(IPC_CHANNELS.workspacesDismissHint, async () => {
392	    await requireRegistry().dismissHint();
393	    await broadcastState();
394	  });
395	  ipcMain.on(IPC_CHANNELS.workspacesPrepareResult, (_event, result: WorkspacePrepareResult) => {
396	    if (!result || typeof result.requestId !== "number") return;
397	    prepareRequests.answer(result.requestId, result.ok === true);
398	  });
399	}
400	
401	/** Re-list the switcher in every window (the lock changed: a take started or ended). */
402	export function notifyWorkspaceBusyChanged(): void {
403	  if (registry && gate) void broadcastState();
404	}
405

