1	import React, {
2	  createContext,
3	  useCallback,
4	  useContext,
5	  useEffect,
6	  useMemo,
7	  useRef,
8	  useState,
9	} from "react";
10	import { useTranslations } from "@kaipu/i18n";
11	import type {
12	  WorkspaceCreateResult,
13	  WorkspaceEditResult,
14	  WorkspaceRelocateResult,
15	  WorkspaceRemoveResult,
16	  WorkspacesState,
17	  WorkspaceSwitchRefusal,
18	  WorkspaceView,
19	} from "@shared/types/workspaces";
20	import { showToast } from "@renderer/ui/toast-store";
21	import { relocateRefusalMessage } from "./relocate-copy";
22	import { WorkspaceDialog } from "./workspace-dialog";
23	
24	export interface Workspaces {
25	  /** Null until the first list answer. */
26	  state: WorkspacesState | null;
27	  /**
28	   * Bumped by every switch (a new generation), never by the first answer: keyed on it, the
29	   * routes remount, so nothing of the old workspace (an editor, a list, a filter, a cached
30	   * thumbnail URL) stays mounted.
31	   */
32	  epoch: number;
33	  active: WorkspaceView | null;
34	  /** The switcher menu (one, in the header); the Record page's Switch opens it too. */
35	  menuOpen: boolean;
36	  setMenuOpen(open: boolean): void;
37	  switchTo(id: string): Promise<void>;
38	  /** "Use an existing folder…": the folder picker, then adopt the folder and switch to it. */
39	  add(): Promise<void>;
40	  /** "New workspace…": the dialog (name, color, location). */
41	  openCreateDialog(): void;
42	  /** "Edit": the same dialog on an existing workspace (name and color). */
43	  openEditDialog(id: string): void;
44	  remove(id: string): Promise<WorkspaceRemoveResult>;
45	  openFolder(id: string): void;
46	  /**
47	   * "Change folder…": the native picker, then the workspace points at the folder where it now
48	   * lives (never moves files). A refusal is explained in a toast.
49	   */
50	  changeFolder(id: string): Promise<void>;
51	  dismissHint(): void;
52	}
53	
54	const WorkspacesContext = createContext<Workspaces | null>(null);
55	
56	/**
57	 * The window's view of the workspace registry (ADR 0032): listed on mount and replaced by
58	 * every `workspaces:changed`, which main sends after a switch, an add, a remove, or a lock
59	 * change (a take starting or ending). Mounted above the routes, so it survives the remount
60	 * a switch causes.
61	 */
62	export function WorkspacesProvider({ children }: { children: React.ReactNode }): React.JSX.Element {
63	  const t = useTranslations("workspaces");
64	  const [state, setState] = useState<WorkspacesState | null>(null);
65	  const [menuOpen, setMenuOpen] = useState(false);
66	  const [epoch, setEpoch] = useState(0);
67	  // The dialog: "new", or the id of the workspace being edited.
68	  const [dialog, setDialog] = useState<"new" | { editId: string } | null>(null);
69	  const generation = useRef<number | null>(null);
70	
71	  useEffect(() => {
72	    let alive = true;
73	    const off = window.electronAPI.workspaces.onChanged((next) => {
74	      if (!alive) return;
75	      if (generation.current !== null && generation.current !== next.generation) {
76	        setEpoch((n) => n + 1);
77	        setMenuOpen(false);
78	      }
79	      generation.current = next.generation;
80	      setState(next);
81	    });
82	    void window.electronAPI.workspaces
83	      .list()
84	      .then((first) => {
85	        // A broadcast that already arrived is newer than this answer.
86	        if (!alive || generation.current !== null) return;
87	        generation.current = first.generation;
88	        setState(first);
89	      })
90	      .catch((error: unknown) => console.error("workspaces: list failed", error));
91	    return () => {
92	      alive = false;
93	      off();
94	    };
95	  }, []);
96	
97	  const active = useMemo(
98	    () => state?.workspaces.find((w) => w.id === state.activeId) ?? null,
99	    [state],
100	  );
101	
102	  const explain = useCallback(
103	    (reason: WorkspaceSwitchRefusal, target: WorkspaceView | undefined): void => {
104	      // Cancelled is the user's own answer (Keep editing); it needs no toast.
105	      if (reason === "cancelled" || reason === "unknown") return;
106	      const message =
107	        reason === "unavailable"
108	          ? t("switchRefusedUnavailable", { name: target?.name ?? "" })
109	          : reason === "read-only"
110	            ? t("readOnly")
111	            : t("switchRefusedBusy");
112	      showToast({ message });
113	    },
114	    [t],
115	  );
116	
117	  const switchTo = useCallback(
118	    async (id: string): Promise<void> => {
119	      setMenuOpen(false);
120	      const result = await window.electronAPI.workspaces.switch(id);
121	      if (!result.ok)
122	        explain(
123	          result.reason,
124	          state?.workspaces.find((w) => w.id === id),
125	        );
126	    },
127	    [explain, state],
128	  );
129	
130	  const add = useCallback(async (): Promise<void> => {
131	    setMenuOpen(false);
132	    const result = await window.electronAPI.workspaces.add();
133	    if (!result.ok && result.reason === "read-only") showToast({ message: t("readOnly") });
134	  }, [t]);
135	
136	  const openCreateDialog = useCallback((): void => {
137	    setMenuOpen(false);
138	    setDialog("new");
139	  }, []);
140	
141	  const openEditDialog = useCallback((id: string): void => {
142	    setMenuOpen(false);
143	    setDialog({ editId: id });
144	  }, []);
145	
146	  const onCreated = useCallback(
147	    (result: Extract<WorkspaceCreateResult, { ok: true }>): void => {
148	      setDialog(null);
149	      // The workspace exists either way; only the switch to it can have been refused.
150	      if (!result.switchResult.ok) explain(result.switchResult.reason, result.workspace);
151	    },
152	    [explain],
153	  );
154	
155	  const onSaved = useCallback(
156	    (result: Extract<WorkspaceEditResult, { ok: true }>): void => {
157	      setDialog(null);
158	      if (!result.savedToFolder) {
159	        showToast({ message: t("editSavedOffline", { name: result.workspace.name }) });
160	      }
161	    },
162	    [t],
163	  );
164	
165	  const onRelocated = useCallback(
166	    (result: Extract<WorkspaceRelocateResult, { ok: true }>): void => {
167	      // The picker opens on the current folder, so picking it as-is is easy: say nothing.
168	      if (result.unchanged) return;
169	      showToast({ message: t("folderChanged", { name: result.workspace.name }) });
170	    },
171	    [t],
172	  );
173	
174	  const changeFolder = useCallback(
175	    async (id: string): Promise<void> => {
176	      let result: Awaited<ReturnType<typeof window.electronAPI.workspaces.relocate>>;
177	      try {
178	        result = await window.electronAPI.workspaces.relocate(id);
179	      } catch {
180	        // Rejected after main may already have applied the new folder: the result is unknown.
181	        showToast({ message: t("relocateUncertain") });
182	        return;
183	      }
184	      if (result.ok) {
185	        onRelocated(result);
186	        return;
187	      }
188	      const name = state?.workspaces.find((w) => w.id === id)?.name ?? "";
189	      const message = relocateRefusalMessage(result, name, t);
190	      if (message) showToast({ message });
191	    },
192	    [onRelocated, state, t],
193	  );
194	
195	  const remove = useCallback(
196	    async (id: string): Promise<WorkspaceRemoveResult> => {
197	      const result = await window.electronAPI.workspaces.remove(id);
198	      if (!result.ok) {
199	        // A race can refuse it (it became the active one after the dialog opened): the
200	        // dialog is gone, so the toast is the only place the reason can show.
201	        const name = state?.workspaces.find((w) => w.id === id)?.name ?? "";
202	        const message =
203	          result.reason === "active"
204	            ? t("removeRefusedActive", { name })
205	            : result.reason === "last"
206	              ? t("removeRefusedLast")
207	              : result.reason === "read-only"
208	                ? t("readOnly")
209	                : t("removeRefusedUnknown");
210	        showToast({ message });
211	      }
212	      return result;
213	    },
214	    [state, t],
215	  );
216	
217	  const value = useMemo<Workspaces>(
218	    () => ({
219	      state,
220	      epoch,
221	      active,
222	      menuOpen,
223	      setMenuOpen,
224	      switchTo,
225	      add,
226	      openCreateDialog,
227	      openEditDialog,
228	      remove,
229	      openFolder: (id) => void window.electronAPI.workspaces.openFolder(id),
230	      changeFolder,
231	      dismissHint: () => void window.electronAPI.workspaces.dismissHint(),
232	    }),
233	    [
234	      state,
235	      epoch,
236	      active,
237	      menuOpen,
238	      switchTo,
239	      add,
240	      openCreateDialog,
241	      openEditDialog,
242	      remove,
243	      changeFolder,
244	    ],
245	  );
246	
247	  const editing =
248	    dialog && dialog !== "new"
249	      ? (state?.workspaces.find((w) => w.id === dialog.editId) ?? null)
250	      : null;
251	  // An edit of a workspace that left the list meanwhile has nothing to show.
252	  const showDialog = state !== null && (dialog === "new" || (dialog !== null && editing !== null));
253	
254	  return (
255	    <WorkspacesContext.Provider value={value}>
256	      {children}
257	      {showDialog && state && (
258	        <WorkspaceDialog
259	          // A fresh form per target: the fields start from that workspace, not the last one.
260	          key={editing?.id ?? "new"}
261	          state={state}
262	          editing={editing}
263	          onClose={() => setDialog(null)}
264	          onUseExisting={() => {
265	            setDialog(null);
266	            void add();
267	          }}
268	          onCreated={onCreated}
269	          onSaved={onSaved}
270	          onRelocated={onRelocated}
271	        />
272	      )}
273	    </WorkspacesContext.Provider>
274	  );
275	}
276	
277	export function useWorkspaces(): Workspaces {
278	  const value = useContext(WorkspacesContext);
279	  if (!value) throw new Error("useWorkspaces must be used inside <WorkspacesProvider>");
280	  return value;
281	}
282	
283	/** Same as `useWorkspaces`, or null outside the provider (pages rendered alone in tests). */
284	export function useOptionalWorkspaces(): Workspaces | null {
285	  return useContext(WorkspacesContext);
286	}
