1	import { mkdir, readFile, rm, rmdir, stat } from "node:fs/promises";
2	import { join } from "node:path";
3	import { isTagColor, TAG_COLORS, type TagColor } from "@kaipu/domain/constants";
4	import { normalizeWorkspaceName } from "@shared/workspace-name";
5	import { atomicWriteFile } from "../library/atomic-write";
6	
7	export { normalizeWorkspaceName };
8	
9	/**
10	 * `.kaipu/workspace/identity.json`: the workspace's id, name, color and initials, inside the
11	 * folder so they travel with it (ADR 0032). It is in a SUBFOLDER of `.kaipu/`, never beside
12	 * the sidecars: a sidecar is `.kaipu/<stem>.json`, so a customer's `workspace.png` already owns
13	 * `.kaipu/workspace.json`, and no media stem can address a folder.
14	 */
15	export const IDENTITY_DIR = join(".kaipu", "workspace");
16	export const IDENTITY_FILE = join(IDENTITY_DIR, "identity.json");
17	
18	/** The migrated library's name (spec decision 22), and its initials. */
19	export const DEFAULT_WORKSPACE_NAME = "Default workspace";
20	
21	/** Kaipu's brand color (#F6055C): the migrated library wears it, the user can change it. */
22	export const DEFAULT_WORKSPACE_COLOR: TagColor = "kaipu";
23	
24	export interface WorkspaceIdentity {
25	  version: 1;
26	  id: string;
27	  name: string;
28	  color: TagColor;
29	  /** 1–2 characters; derived from the name when absent. */
30	  initials?: string;
31	  createdAt: number;
32	}
33	
34	export type IdentityRead =
35	  | { kind: "ok"; identity: WorkspaceIdentity }
36	  /** No identity file: a folder from before workspaces, or a plain folder. */
37	  | { kind: "absent" }
38	  /** The file is there but cannot be read or is not an identity. Never overwritten. */
39	  | { kind: "unreadable" };
40	
41	/** An id that cannot leave the folder it names: no separators, no dots-only. */
42	export function isSafeWorkspaceId(value: unknown): value is string {
43	  return (
44	    typeof value === "string" &&
45	    value.length > 0 &&
46	    value.length <= 64 &&
47	    /^[A-Za-z0-9-]+$/.test(value)
48	  );
49	}
50	
51	/** First letter of the first two words, upper-cased: "Default workspace" → "DW". */
52	export function deriveInitials(name: string): string {
53	  const letters = name
54	    .trim()
55	    .split(/\s+/)
56	    .filter(Boolean)
57	    .slice(0, 2)
58	    .map((word) => Array.from(word)[0] ?? "")
59	    .join("");
60	  return letters.toLocaleUpperCase() || "?";
61	}
62	
63	export function isValidInitials(value: unknown): value is string {
64	  if (typeof value !== "string") return false;
65	  const length = Array.from(value.trim()).length;
66	  return length >= 1 && length <= 2;
67	}
68	
69	/** The next palette color no registered workspace uses yet (cycles once all are taken). */
70	export function nextWorkspaceColor(used: readonly TagColor[]): TagColor {
71	  return (
72	    TAG_COLORS.find((color) => !used.includes(color)) ??
73	    TAG_COLORS[used.length % TAG_COLORS.length]!
74	  );
75	}
76	
77	/**
78	 * Read a folder's identity. An unknown color or invalid initials fall back on read and the
79	 * file is NOT rewritten (spec, Data shapes).
80	 */
